'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const currentMonth=()=>today().slice(0,7);const currentYear=()=>today().slice(0,4);
const formatDate=d=>new Date(d+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'});
const monthName=m=>new Date(m+'-15T12:00:00').toLocaleDateString('it-IT',{month:'long',year:'numeric'});
const categories=['Alimentari','Affitto','Trasporti','Svago','Altro'];
const colors=['#00875a','#f2bd50','#5e9bb6','#dc865b','#a4b29d'];
const paths={Home:'M3 10l9-7 9 7v10H5V10M9 20v-7h6v7',Offerte:'M3 3h8l10 10-8 8L3 11V3M7 7h.01',Spese:'M4 20V10m8 10V4m8 16v-8',Budget:'M12 3a9 9 0 1 0 9 9h-9V3m3 0a6 6 0 0 1 6 6h-6V3',Profilo:'M20 21v-3a8 8 0 0 0-16 0v3M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',plus:'M12 5v14M5 12h14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',search:'M21 21l-6-6M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.Offerte}"/></svg>`;
const pig=`<svg viewBox="0 0 110 100" class="logo-pig" aria-hidden="true"><path d="M28 51c-8 1-12 7-10 14l7 8 1 12h11l4-8h28l5 8h10l1-15 10-5V52H84c-3-8-12-14-24-14-15 0-26 5-32 13Z"/><path d="m24 54-9-9 1 17M76 53h1M38 48h19M36 29v10m37-10v12M24 21 55 7l33 14-33 13-31-13Zm64 0v22"/><path d="M18 61c-15 0-11-15-4-11"/></svg>`;
const photos={tomato:'https://images.unsplash.com/photo-1546094096-0df4bcaaa337?w=600&auto=format&fit=crop',grapes:'https://images.unsplash.com/photo-1537640538966-79f369143f8f?w=600&auto=format&fit=crop',pasta:'https://images.unsplash.com/photo-1551462147-37885acc36f1?w=600&auto=format&fit=crop',milk:'https://images.unsplash.com/photo-1563636619-e9143da7973b?w=600&auto=format&fit=crop'};
const offers=[{id:1,name:'Pomodori ciliegino',store:'Conad',cat:'Alimentari',diet:['Vegetariana','Vegana','Senza glutine'],price:1.39,old:1.99,discount:30,size:'Vaschetta · 500 g',img:photos.tomato},{id:2,name:'Uva bianca da tavola',store:'Conad',cat:'Alimentari',diet:['Vegetariana','Vegana','Senza glutine'],price:2.39,old:3.99,discount:40,size:'Al kg · Origine Italia',img:photos.grapes},{id:3,name:'Pasta di semola',store:'Carrefour',cat:'Alimentari',diet:['Vegetariana','Vegana'],price:1.23,old:1.89,discount:35,size:'Confezione · 500 g',img:photos.pasta},{id:4,name:'Latte intero UHT',store:'Pam',cat:'Alimentari',diet:['Vegetariana','Senza glutine'],price:0.99,old:1.39,discount:29,size:'Confezione · 1 L',img:photos.milk},{id:5,name:'Pasta di semola',store:'Todis',cat:'Alimentari',diet:['Vegetariana','Vegana'],price:0.79,old:0.99,discount:20,size:'Confezione · 500 g',img:photos.pasta}];
const supermarkets=['Conad','Carrefour','Pam','Todis'];
const official={Conad:'https://www.conad.it/',Carrefour:'https://www.carrefour.it/',Pam:'https://www.pampanorama.it/',Todis:'https://www.todis.it/'};
const zones={'San Lorenzo, Roma':[41.8986,12.5164],'Piazza Bologna, Roma':[41.9137,12.5214],'Via del Lavoro, San Lazzaro':[44.471,11.411],'Centro, Roma':[41.9028,12.4964]};
let state=null,identity=null,storageKey='',vaultKey=null,pendingSave=Promise.resolve(),page='Home',selectedMonth=currentMonth(),selectedYear=currentYear(),expensePeriod='month',budgetPeriod='Mensile',query='',category='Tutte',storeFilter='Tutti',onlyFav=false,expiring=false,offerTab='Elenco Offerte',map=null,flyerPage=0,flyerStore='Conad';
const sum=es=>es.reduce((a,e)=>a+Number(e.amount),0);
const monthly=(m=currentMonth())=>(state?.expenses||[]).filter(e=>e.date.slice(0,7)===m);
const spent=(m=currentMonth())=>sum(monthly(m));
const budgetFor=(m=currentMonth())=>Number(state?.budgets?.[m]??state?.budget??800);
const pct=(m=currentMonth())=>Math.round(spent(m)/budgetFor(m)*100);
function previousMonth(m){const d=new Date(m+'-15T12:00:00');d.setMonth(d.getMonth()-1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
function defaultState(){return {version:2,name:'',email:identity?.email||'',birth:'',zone:'San Lorenzo, Roma',coords:null,budget:800,budgets:{},diet:'Nessuna preferenza',categories:['Alimentari','Trasporti','Svago'],stores:[...supermarkets],favorites:[],notices:true,dark:false,expenses:[],onboarded:false}}
function normalize(s){s={...defaultState(),...s};s.expenses=(s.expenses||[]).map(e=>({...e,id:e.id||crypto.randomUUID(),category:e.category==='Tempo libero'?'Svago':e.category}));s.categories=s.categories.map(c=>c==='Tempo libero'?'Svago':c);return s}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4000)}
function error(s){return `<p class="error" role="alert">${esc(s)}</p>`}
const toB64=bytes=>{const arr=new Uint8Array(bytes);let text='';for(let i=0;i<arr.length;i+=8192)text+=String.fromCharCode(...arr.subarray(i,i+8192));return btoa(text)};
const fromB64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function deriveKey(pin,salt){const k=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},k,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptState(s,k,salt){const iv=crypto.getRandomValues(new Uint8Array(12));return {encrypted:true,salt:toB64(salt),iv:toB64(iv),data:toB64(await crypto.subtle.encrypt({name:'AES-GCM',iv},k,new TextEncoder().encode(JSON.stringify(s))))}}
function save(){const snapshot=structuredClone(state),key=vaultKey,k=storageKey;pendingSave=pendingSave.catch(()=>{}).then(async()=>{try{if(key){const old=JSON.parse(localStorage.getItem(k));localStorage.setItem(k,JSON.stringify(await encryptState(snapshot,key,fromB64(old.salt))))}else localStorage.setItem(k,JSON.stringify(snapshot))}catch{toast('Salvataggio non riuscito: controlla lo spazio disponibile nel browser.');throw Error('Salvataggio non riuscito')}});return pendingSave}
function applyTheme(){document.body.classList.toggle('dark',!!state?.dark)}
function shell(){applyTheme();document.body.classList.remove('welcome');$('shell').innerHTML=`<aside><div class="brand"><span class="logo">${pig}</span>StudentSave<span style="color:#98b487">.</span></div><p class="tagline">Risparmia meglio. Vivi di più.</p><nav id="nav"></nav><div class="side-tip">🌱<b>Piccole scelte, grandi risparmi.</b>Il tuo prossimo obiettivo è più vicino, un euro alla volta.</div><div class="user"><div class="avatar">👨🏻‍🎓</div><div><b>${esc(state.name)}</b><div class="tiny">Il tuo spazio studente</div></div><button class="link" onclick="go('Profilo')" aria-label="Apri profilo">〉</button></div></aside><main><header class="top"><div class="crumb">Il tuo spazio, i tuoi obiettivi.</div><div class="brand mobile-brand">${pig} StudentSave.</div><div class="top-right"><span class="tiny">${esc(monthName(currentMonth()))}</span><button class="circle-btn" aria-label="Cerca offerte" onclick="go('Offerte');$('search-offers')?.focus()">${icon('search')}</button><button class="circle-btn" aria-label="Notifiche" onclick="notifications()">${icon('bell')}</button><button class="avatar" aria-label="Profilo" onclick="go('Profilo')">👨🏻‍🎓</button></div></header><div id="app"></div><footer class="footer"><span>StudentSave © ${currentYear()} · Fatto per la vita universitaria.</span><span>Dati personali su questo dispositivo · Offerte di esempio</span></footer></main>`}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'smooth'})}
function heading(t,s,button=true){return `<div class="headline"><div><h1>${t}</h1><p class="subtitle">${s}</p></div>${button?`<button class="primary" onclick="expense()">${icon('plus')} Aggiungi spesa</button>`:''}</div>`}
function budgetCard(){const n=spent(),b=budgetFor();return `<div class="card budget-card"><div><div class="eyebrow">Il tuo budget di ${esc(monthName(currentMonth()))}</div><div class="money">${euro(b-n)}</div><div class="sub">${n<=b?'ancora a disposizione questo mese':'saldo oltre il budget mensile'}</div><div class="budget-bottom"><div>Hai speso<b>${euro(n)}</b></div><div>Budget mensile<b>${euro(b)}</b></div></div></div><div class="ring" style="--progress:${Math.min(pct(),100)}%"><div><strong>${pct()}%</strong><span>del budget usato</span></div></div></div>`}
function personalized(){return offers.filter(o=>state.stores.includes(o.store)&&state.categories.includes(o.cat)&&(state.diet==='Nessuna preferenza'||o.diet.includes(state.diet)))}
function offerCard(o){return `<article class="card offer"><div class="photo"><button style="border:0;padding:0;width:100%;height:100%;display:block" onclick="detail(${o.id})" aria-label="Dettagli ${esc(o.name)}"><img src="${o.img}" alt="${esc(o.name)}" loading="lazy"></button><span class="discount">−${o.discount}%</span><button class="heart" aria-label="${state.favorites.includes(o.id)?'Rimuovi dai':'Aggiungi ai'} preferiti" onclick="favorite(${o.id})">${state.favorites.includes(o.id)?'♥':'♡'}</button></div><div class="offer-content"><div class="store">${o.store==='Conad'?'✿ ':''}${o.store.toUpperCase()}</div><h3><button class="link" style="padding:0;text-align:left;font-size:13px" onclick="detail(${o.id})">${o.name}</button></h3><div class="size">${o.size}</div><div class="price">${euro(o.price)} <del>${euro(o.old)}</del></div><div class="offer-foot"><span>Offerta di esempio</span><span>Entro ${formatDate(exampleExpiry())}</span></div><span class="match">✓ In linea con le tue preferenze</span></div></article>`}
function exampleExpiry(){let d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function emptyOffers(){return `<div class="empty">Nessuna offerta corrisponde alle tue scelte.<br><br><button class="link" onclick="query='';category='Tutte';storeFilter='Tutti';onlyFav=false;expiring=false;render()">Azzera i filtri</button> · <button class="link" onclick="go('Profilo')">Modifica le preferenze →</button></div>`}
function favorite(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(page==='Offerte'&&offerTab==='Elenco Offerte')updateOffers();else render()}
function transaction(e,editable=false){return `<div class="transaction"><span class="tx-icon">${({Alimentari:'🛒',Affitto:'🏠',Trasporti:'🚍',Svago:'☕',Altro:'🧾'})[e.category]||'🧾'}</span><div class="tx-name"><b>${esc(e.name)}</b><span class="tiny">${esc(e.category)} · ${formatDate(e.date)}</span>${e.note?`<div class="tiny" style="margin-top:4px">${esc(e.note)}</div>`:''}</div><span class="tx-amount">−${euro(e.amount)}</span>${editable?`<div class="tx-actions"><button class="icon-action" aria-label="Modifica ${esc(e.name)}" onclick="expense('${e.id}')">✎</button><button class="icon-action text-danger" aria-label="Elimina ${esc(e.name)}" onclick="deleteExpense('${e.id}')">×</button></div>`:''}</div>`}
function compare(current,previous){if(!previous)return current?'Nessuna spesa nel periodo precedente':'Nessuna variazione';const delta=(current-previous)/previous*100;return `${delta<=0?'↘':'↗'} ${Math.abs(delta).toFixed(0)}% rispetto al periodo precedente`}
function monthlyBars(year=currentYear(),allYear=false){const count=allYear?12:5,entries=[];for(let i=0;i<count;i++){let d=allYear?new Date(Number(year),i,15):new Date(currentMonth()+'-15T12:00:00');if(!allYear)d.setMonth(d.getMonth()-(count-1-i));let m=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');entries.push({m,n:spent(m),label:d.toLocaleDateString('it-IT',{month:'short'})})}const max=Math.max(...entries.map(e=>e.n),1);return `<div class="chart ${allYear?'year-bars':''}" role="img" aria-label="Spese mensili: ${esc(entries.map(e=>e.label+' '+euro(e.n)).join(', '))}">${entries.map(e=>`<div class="bar-wrap"><div class="bar ${e.m===currentMonth()?'current':''}" style="height:${e.n?Math.max(4,e.n/max*95):2}px" title="${esc(e.label+' '+euro(e.n))}"></div><span>${esc(e.label)}</span></div>`).join('')}</div>`}
function homeChart(){return `<div class="summary-title"><h2>Le tue spese</h2><span class="pill">Ultimi 5 mesi</span></div>${monthlyBars()}<div class="statline"><b>${euro(spent())}</b></div><p class="tiny" style="margin-top:10px">${compare(spent(),spent(previousMonth(currentMonth())))}</p>`}
function budgetAdvice(m=currentMonth()){let p=pct(m);if(p>=100)return `Hai ${p>100?'superato':'raggiunto'} il budget di ${monthName(m)}. Rivedi le spese e il tuo obiettivo.`;if(p>=80)return `Attenzione: hai utilizzato il ${p}% del budget mensile. Ti restano ${euro(budgetFor(m)-spent(m))}.`;if(p>=50)return `Hai utilizzato il ${p}% del budget. Tieni d'occhio le categorie e pianifica le prossime spese.`;return `Hai ancora ${euro(budgetFor(m)-spent(m))} a disposizione. Piccoli risparmi ogni giorno ti aiutano a raggiungere i tuoi obiettivi.`}
function home(){return heading(`Ciao, ${esc(state.name.split(' ')[0])}! 👋`,'Un piccolo risparmio oggi, più possibilità domani.')+`<div class="grid"><div>${budgetCard()}<div class="section-head"><h2>Offerte scelte per te 🌿</h2><button class="link" onclick="go('Offerte')">Vedi tutte →</button></div><p class="tiny" style="margin:-6px 0 16px">${esc(state.zone)} · Selezione dimostrativa in base al tuo profilo</p><div class="offers">${personalized().slice(0,3).map(offerCard).join('')||emptyOffers()}</div><div class="insight"><div class="bubble">💡</div><div><h3>Il consiglio per il tuo budget</h3><p>${esc(budgetAdvice())}</p></div></div></div><div class="right"><div class="card">${homeChart()}</div><div class="card transactions"><div class="summary-title"><h2>Ultime spese</h2><button class="link" onclick="go('Spese')">Tutte →</button></div>${monthly().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(e=>transaction(e)).join('')||'<p class="subtitle">Nessuna spesa questo mese. Aggiungi la prima!</p>'}</div><div class="card profile-banner"><span style="font-size:25px">✨</span><div><b style="font-size:12px">Un’app che ti conosce</b><p>Aggiorna i tuoi interessi e scopri<br>offerte più adatte a te.</p></div><button class="link" onclick="go('Profilo')" aria-label="Modifica preferenze">→</button></div></div></div>`}
function zoneSelector(){return `<div class="page-controls"><label for="zone-pick">⌖ La tua zona</label><select id="zone-pick" onchange="changeZone(this.value)">${Object.keys(zones).map(z=>`<option ${state.zone===z?'selected':''}>${esc(z)}</option>`).join('')}${!zones[state.zone]?`<option selected>${esc(state.zone)}</option>`:''}<option value="custom">Inserisci un'altra zona…</option></select><button class="secondary" onclick="useGPS()">◎ Usa GPS</button></div>`}
function offersView(){return heading('Offerte e volantini','I tuoi supermercati, le tue preferenze. Tutto a portata di mano.',false)+zoneSelector()+`<div class="notice">Prezzi, scadenze e punti sulla mappa sono esempi dimostrativi, non dati dei negozi in tempo reale. Per i volantini aggiornati usa i siti ufficiali.</div><div class="filters"><input id="search-offers" aria-label="Cerca prodotti, supermercati o volantini" placeholder="Cerca prodotti, supermercati o volantini…" value="${esc(query)}" oninput="query=this.value;updateOfferContent()"><select aria-label="Categoria" onchange="category=this.value;updateOfferContent()"><option ${category==='Tutte'?'selected':''}>Tutte</option>${categories.map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select><select aria-label="Supermercato" onchange="storeFilter=this.value;updateOfferContent()"><option value="Tutti">Tutti</option>${supermarkets.map(s=>`<option ${storeFilter===s?'selected':''}>${s}</option>`).join('')}</select><button class="secondary" aria-pressed="${onlyFav}" onclick="onlyFav=!onlyFav;render()">${onlyFav?'♥':'♡'} Preferiti</button><button class="secondary" aria-pressed="${expiring}" onclick="expiring=!expiring;render()">${expiring?'✓ ':''}In scadenza</button></div><div class="tabs" role="group" aria-label="Vista offerte">${['Elenco Offerte','Mappa','Volantini'].map(t=>`<button class="${offerTab===t?'active':''}" aria-pressed="${offerTab===t}" onclick="offerTab='${t}';render()">${t}</button>`).join('')}</div><div id="offer-content"></div>`}
function filteredOffers(){return personalized().filter(o=>(o.name+' '+o.store).toLowerCase().includes(query.toLowerCase())&&(category==='Tutte'||category===o.cat)&&(storeFilter==='Tutti'||o.store===storeFilter)&&(!onlyFav||state.favorites.includes(o.id))&&(!expiring||exampleExpiry()<=nextDate(today(),3)))}
function nextDate(date,days){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}
function updateOffers(){updateOfferContent()}
function updateOfferContent(){if(map){map.remove();map=null}const el=$('offer-content');if(!el)return;let filtered=filteredOffers();if(offerTab==='Elenco Offerte'){el.innerHTML=`<div class="offers full" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr))">${filtered.map(offerCard).join('')||emptyOffers()}</div>`}else if(offerTab==='Volantini'){const stores=supermarkets.filter(s=>state.stores.includes(s)&&(storeFilter==='Tutti'||storeFilter===s)&&(!query||('volantino '+s).toLowerCase().includes(query.toLowerCase())||filtered.some(o=>o.store===s)));el.innerHTML=`<div class="notice">Gli sfogliabili interni sono esempi. Le preferenze alimentari si applicano alle singole offerte; un volantino può contenere anche altri prodotti. I filtri Preferiti, Categoria e In scadenza riguardano l'elenco delle offerte.</div><div class="offers full">${stores.map(s=>`<div class="card"><div class="flyer-cover"><div class="store">${s.toUpperCase()}</div><h2>La spesa che conviene</h2><p class="fine">Esempio di volantino · ${esc(state.zone)}</p><span style="font-size:42px">🛒</span></div><div class="action-row" style="margin-top:15px"><button class="primary" onclick="openFlyer('${s}')">Sfoglia esempio</button><a class="link" href="${official[s]}" target="_blank" rel="noopener noreferrer">Sito ufficiale ↗</a></div></div>`).join('')||emptyOffers()}</div>`}else{el.innerHTML=`<div class="card"><p class="fine" style="margin-bottom:15px">Punti illustrativi intorno alla zona selezionata, non posizioni reali dei punti vendita.</p><div class="map-area" id="map"></div><div id="map-offer" style="margin-top:15px"></div></div>`;initMap(filtered)}}
function initMap(list){if(!window.L){$('map').innerHTML='<div class="empty">La mappa non è disponibile: il servizio esterno non si è caricato. Puoi usare l’elenco offerte.</div>';return}const center=state.coords||zones[state.zone]||zones['Centro, Roma'];map=L.map('map').setView(center,15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).addTo(map);L.circleMarker(center,{radius:7,color:'#00875a',fillOpacity:1}).addTo(map).bindPopup('Zona selezionata');list.forEach((o,i)=>{const point=[center[0]+(i%2?.003:-.0025)*(1+i*.15),center[1]+(i%3-1)*.0035];const marker=L.marker(point,{icon:L.divIcon({className:'',html:`<span class="map-price">${o.store} −${o.discount}%</span>`,iconSize:[110,30]})}).addTo(map);marker.bindPopup(`<b>${o.store}</b><br>${o.name}<br>${euro(o.price)} · Punto illustrativo`);marker.on('click',()=>{$('map-offer').innerHTML=`<div class="summary-title"><div><b>${o.store} · ${o.name}</b><p class="subtitle">${euro(o.price)} · Esempio, posizione indicativa</p></div><button class="primary" onclick="detail(${o.id})">Dettagli</button></div>`})});if(!list.length)$('map-offer').innerHTML='<p class="subtitle">Nessuna offerta corrisponde ai filtri selezionati.</p>'}
function changeZone(z){if(z==='custom'){openModal(`<div class="modal-head"><h2>La tua zona</h2>${closeButton()}</div><form class="modal-form" onsubmit="event.preventDefault();state.zone=this.zone.value.trim();state.coords=null;save();closeModal();render()"><label class="label-input">Indirizzo o città universitaria<input name="zone" required maxlength="150" value="${esc(state.zone)}"></label><p class="fine">Senza coordinate GPS, la mappa mostra un centro indicativo di Roma. Le offerte restano dimostrative.</p><button class="primary">Salva zona</button></form>`);return}state.zone=z;state.coords=null;save();render()}
function useGPS(onboarding=false){if(!navigator.geolocation){toast('La geolocalizzazione non è supportata da questo browser. Inserisci la zona manualmente.');return}toast('Richiesta posizione in corso…');navigator.geolocation.getCurrentPosition(p=>{const coords=[p.coords.latitude,p.coords.longitude];if(onboarding){$('register-zone').value=`Posizione GPS (${coords[0].toFixed(4)}, ${coords[1].toFixed(4)})`;$('register-zone').dataset.coords=JSON.stringify(coords)}else{state.coords=coords;state.zone=`Posizione GPS (${coords[0].toFixed(4)}, ${coords[1].toFixed(4)})`;save();render()}toast('Posizione aggiornata. Nessuna ricerca reale dei negozi è attiva.')},e=>toast(e.code===1?'Permesso posizione negato. Puoi inserire la zona manualmente.':'Posizione non disponibile. Inserisci la zona manualmente.'),{enableHighAccuracy:false,timeout:12000,maximumAge:60000})}
function filteredExpenses(){return state.expenses.filter(e=>expensePeriod==='year'?e.date.slice(0,4)===selectedYear:e.date.slice(0,7)===selectedMonth)}
function categoryChart(es){const total=sum(es),sums=categories.map(c=>sum(es.filter(e=>e.category===c)));let running=0;const gradient=sums.map((n,i)=>{let start=running;running+=total?n/total*100:0;return `${colors[i]} ${start}% ${running}%`}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:${total?`conic-gradient(${gradient})`:'#e5eae3'}" role="img" aria-label="Ripartizione delle spese per categoria"><div><span><b>${euro(total)}</b><br>totale</span></div></div><div class="legend">${categories.map((c,i)=>`<div class="legend-row"><span><i class="dot" style="background:${colors[i]}"></i>${c}</span><span>${total?(sums[i]/total*100).toFixed(1):0}% · ${euro(sums[i])}</span></div>`).join('')}</div></div>`}
function expensesView(){const es=filteredExpenses();return heading('Le tue spese','Ogni spesa al suo posto. Ogni obiettivo più vicino.')+`<div class="page-controls"><label for="expense-period">Periodo</label><select id="expense-period" onchange="expensePeriod=this.value;render()"><option value="month" ${expensePeriod==='month'?'selected':''}>Mese</option><option value="year" ${expensePeriod==='year'?'selected':''}>Anno</option></select>${expensePeriod==='month'?`<input type="month" aria-label="Mese delle spese" value="${selectedMonth}" onchange="if(this.value){selectedMonth=this.value;render()}">`:`<input type="number" aria-label="Anno delle spese" min="1900" max="2200" value="${selectedYear}" onchange="if(this.checkValidity()){selectedYear=this.value;render()}">`}</div><div class="grid"><div class="card"><div class="summary-title"><h2>Spesa totale</h2><span class="pill">${expensePeriod==='month'?monthName(selectedMonth):selectedYear}</span></div><div class="money">${euro(sum(es))}</div>${monthlyBars(expensePeriod==='year'?selectedYear:selectedMonth.slice(0,4),true)}<div class="section-head"><h2>Categorie</h2></div>${categoryChart(es)}</div><div class="card"><div class="summary-title"><h2>Le tue transazioni</h2><span class="pill">${es.length} spese</span></div>${es.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>transaction(e,true)).join('')||'<div class="empty">Nessuna spesa nel periodo selezionato.</div>'}</div></div>`}
function budgetView(){const m=selectedMonth,y=m.slice(0,4),annual=budgetPeriod==='Annuale',es=annual?state.expenses.filter(e=>e.date.startsWith(y+'-')):monthly(m),n=sum(es),b=annual?Array.from({length:12},(_,i)=>budgetFor(y+'-'+String(i+1).padStart(2,'0'))).reduce((a,b)=>a+b,0):budgetFor(m),p=Math.round(n/b*100);return heading('Il tuo budget','Dai spazio a quello che conta per te.',false)+`<div class="page-controls"><label for="budget-month">Periodo di riferimento</label><input id="budget-month" type="month" value="${selectedMonth}" onchange="if(this.value){selectedMonth=this.value;render()}"></div><div class="grid"><div class="card" style="text-align:center"><div class="choices" style="justify-content:center">${['Mensile','Annuale'].map(p=>`<button class="choice ${budgetPeriod===p?'selected':''}" onclick="budgetPeriod='${p}';render()">${p}</button>`).join('')}</div><p class="subtitle">${annual?y:monthName(m)}</p><div class="ring large-ring" style="--progress:${Math.min(p,100)}%"><div><strong>${p}%</strong><span>del budget usato</span><strong style="font-size:23px;margin-top:10px">${euro(b-n)}</strong><span>rimanenti</span></div></div><p>Spesi: <b>${euro(n)}</b> · Budget: <b>${euro(b)}</b></p>${annual?'<p class="fine" style="margin-top:14px">Somma delle spese registrate nell’anno e dei 12 budget mensili. I mesi senza un budget specifico usano il budget predefinito.</p>':''}</div><div><form class="card" onsubmit="updateBudget(event)"><h2>Imposta il tuo budget</h2><p class="subtitle">Budget per ${monthName(m)}</p><div class="budget-edit"><input name="budget" aria-label="Budget mensile in euro" type="number" min="1" max="100000" step="0.01" required value="${budgetFor(m)}"><button class="primary">Salva budget</button></div><label class="preference-label" style="margin-top:16px"><input type="checkbox" name="default"> Usa anche come budget predefinito per gli altri mesi</label></form><div class="card" style="margin-top:20px"><h2>Rispetto al mese scorso</h2><p class="compare">${compare(spent(m),spent(previousMonth(m)))}</p>${comparisonLine(m)}</div><div class="insight"><span>💡</span><div><h3>Il tuo consiglio</h3><p>${esc(budgetAdvice(m))}</p></div></div></div></div>`}
function updateBudget(e){e.preventDefault();let f=new FormData(e.target);state.budgets[selectedMonth]=Number(f.get('budget'));if(f.has('default'))state.budget=Number(f.get('budget'));save();render();toast('Budget aggiornato in tutte le schermate')}
function comparisonLine(m){const now=monthly(m),prev=monthly(previousMonth(m)),last=new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate();const series=es=>Array.from({length:last},(_,i)=>sum(es.filter(e=>Number(e.date.slice(8))<=i+1)));const a=series(now),b=series(prev),max=Math.max(...a,...b,1);const points=arr=>arr.map((v,i)=>`${10+i/(last-1)*380},${105-v/max*90}`).join(' ');return `<svg class="line-chart" viewBox="0 0 400 120" role="img" aria-label="Spesa cumulativa: mese selezionato ${euro(sum(now))}, mese precedente ${euro(sum(prev))}"><polyline fill="none" stroke="#b8c9ba" stroke-width="2" stroke-dasharray="4 5" points="${points(b)}"/><polyline fill="none" stroke="#00875a" stroke-width="3" points="${points(a)}"/></svg><p class="fine">Verde: mese selezionato · Tratteggio: mese precedente.<br>Totali cumulativi dalle spese registrate, giorno per giorno.</p>`}
function profileView(){return heading('Il tuo profilo','Tu scegli le preferenze. StudentSave si adatta a te.',false)+`<form class="card" onsubmit="saveProfile(event)"><div style="display:flex;align-items:center;gap:15px;margin-bottom:28px"><div class="avatar" style="width:62px;height:62px;font-size:35px">👨🏻‍🎓</div><div><h2>${esc(state.name)}</h2><p class="subtitle">Il tuo percorso verso il risparmio</p></div></div><h2 style="margin-bottom:20px">Le mie informazioni</h2><div class="form-grid"><label class="label-input">Nome e cognome<input name="name" required maxlength="70" value="${esc(state.name)}"></label><label class="label-input">Email del profilo<input name="email" type="email" value="${esc(state.email)}" required><span class="fine">Contatto locale, non verificato. Nessuna email viene inviata.</span></label><label class="label-input">Data di nascita<input name="birth" type="date" max="${today()}" value="${esc(state.birth)}"></label><label class="label-input">Città / indirizzo universitario<input name="zone" required maxlength="150" value="${esc(state.zone)}"></label><label class="label-input">Preferenze alimentari<select name="diet">${['Nessuna preferenza','Vegetariana','Vegana','Senza glutine'].map(d=>`<option ${state.diet===d?'selected':''}>${d}</option>`).join('')}</select></label><div class="wide"><label>Categorie di interesse</label><div class="choices">${['Alimentari','Trasporti','Svago','Altro'].map(c=>`<label class="choice preference-label ${state.categories.includes(c)?'selected':''}"><input type="checkbox" name="categories" value="${c}" ${state.categories.includes(c)?'checked':''}> ${c}</label>`).join('')}</div></div><div class="wide"><label>Supermercati preferiti</label><div class="choices">${supermarkets.map(s=>`<label class="choice preference-label ${state.stores.includes(s)?'selected':''}"><input type="checkbox" name="stores" value="${s}" ${state.stores.includes(s)?'checked':''}> ${s}</label>`).join('')}</div></div><div class="wide"><p class="fine">Le preferenze alimentari filtrano gli esempi. Controlla sempre gli ingredienti sull’etichetta.</p></div><div class="wide"><button class="primary">Salva le mie preferenze</button></div></div></form><div class="card" style="margin-top:22px"><h2>Impostazioni</h2><div class="settings-row"><div><h3>🔒 PIN del dispositivo</h3><p>${vaultKey?'Attivo: dati locali cifrati.':'Proteggi i dati locali con un PIN di 4 cifre.'}</p></div><button class="secondary" onclick="pinSettings()">${vaultKey?'Gestisci':'Imposta'}</button></div><div class="settings-row"><div><h3>Face ID / Touch ID</h3><p>Non disponibile in questa web-app. La biometria nativa richiede un’integrazione dedicata.</p></div><span class="pill">Non disponibile</span></div><div class="settings-row"><div><h3>🔔 Preferenze notifiche</h3><p>Mostra le offerte selezionate negli avvisi dell’app.</p></div><input class="toggle" type="checkbox" aria-label="Avvisi sulle offerte" ${state.notices?'checked':''} onchange="state.notices=this.checked;save()"></div><div class="settings-row"><div><h3>🌙 Modalità scura</h3><p>Un’interfaccia più confortevole nelle ore serali.</p></div><input class="toggle" type="checkbox" aria-label="Modalità scura" ${state.dark?'checked':''} onchange="state.dark=this.checked;save();applyTheme()"></div><div class="settings-row"><div><h3>❓ Assistenza e FAQ</h3><p>Risposte su dati, budget e utilizzo dell’app.</p></div><button class="link" onclick="faq()">Apri →</button></div><div class="settings-row"><div><h3>ℹ️ Informazioni e privacy</h3><p>Versione, dati salvati e limiti delle offerte.</p></div><button class="link" onclick="about()">Apri →</button></div><div class="profile-actions"><button class="secondary" onclick="exportData()">Esporta i miei dati</button>${vaultKey?'<button class="secondary" onclick="lockApp()">Blocca con PIN</button>':''}<button class="secondary text-danger" onclick="logout()">Esci dal profilo</button></div></div>`}
function saveProfile(e){e.preventDefault();const f=new FormData(e.target),newZone=f.get('zone').trim();state.name=f.get('name').trim()||'Studente';state.email=f.get('email').trim();state.birth=f.get('birth');if(newZone!==state.zone)state.coords=null;state.zone=newZone;state.diet=f.get('diet');state.categories=f.getAll('categories');state.stores=f.getAll('stores');save();shell();render();toast('Profilo salvato. Le tue offerte sono aggiornate.')}
function render(){if(!state?.onboarded)return;applyTheme();if(map){map.remove();map=null}if(!$('app'))shell();$('nav').innerHTML=['Home','Offerte','Spese','Budget','Profilo'].map(p=>`<button class="${page===p?'active':''}" ${page===p?'aria-current="page"':''} onclick="go('${p}')">${icon(p)}<span>${p}</span></button>`).join('');$('app').innerHTML=({Home:home,Offerte:offersView,Spese:expensesView,Budget:budgetView,Profilo:profileView}[page]||home)();if(page==='Offerte')updateOfferContent()}
const closeButton=()=>'<button class="close" aria-label="Chiudi" onclick="closeModal()">×</button>';
function openModal(html){const m=$('modal');if(m.open)m.close();m.innerHTML=html;m.showModal()}
function closeModal(){$('modal').close()}
function expense(id){const e=id?state.expenses.find(e=>e.id===id):null;openModal(`<div class="modal-head"><h2>${e?'Modifica':'Aggiungi'} spesa</h2>${closeButton()}</div><form class="modal-form" onsubmit="saveExpense(event,'${id||''}')"><label class="label-input">Data<input name="date" type="date" required min="1900-01-01" max="2200-12-31" value="${e?e.date:today()}"></label><label class="label-input">Importo (€)<input name="amount" type="number" min="0.01" max="1000000" step="0.01" placeholder="24,50" required value="${e?e.amount:''}"></label><label class="label-input">Categoria<select name="category">${categories.map(c=>`<option ${e?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="label-input">Supermercato / luogo<input name="name" list="stores" required maxlength="80" placeholder="Es. Conad" value="${esc(e?.name||'')}"><datalist id="stores">${supermarkets.map(s=>`<option>${s}</option>`).join('')}</datalist></label><label class="label-input">Note (facoltative)<input name="note" maxlength="200" placeholder="Es. La spesa della settimana" value="${esc(e?.note||'')}"></label><button class="primary" style="justify-content:center">Salva spesa</button><p class="fine">Il budget del mese della spesa si aggiorna automaticamente.</p></form>`)}
function saveExpense(event,id){event.preventDefault();const f=new FormData(event.target),n=Number(f.get('amount')),name=f.get('name').trim(),date=f.get('date');if(!name||!Number.isFinite(n)||n<=0||n>1000000||!/^\d{4}-\d{2}-\d{2}$/.test(date)){toast('Controlla importo, data e luogo della spesa.');return}const record={id:id||crypto.randomUUID(),name,amount:Math.round(n*100)/100,date,category:f.get('category'),note:f.get('note')};if(id)state.expenses=state.expenses.map(e=>e.id===id?record:e);else state.expenses.unshift(record);save();closeModal();render();toast(id?'Spesa modificata. Budget aggiornato.':'Spesa aggiunta. Budget aggiornato.')}
function deleteExpense(id){const e=state.expenses.find(e=>e.id===id);if(!e)return;openModal(`<div class="modal-head"><h2>Eliminare questa spesa?</h2>${closeButton()}</div><p class="subtitle">${esc(e.name)} · ${euro(e.amount)} · ${formatDate(e.date)}</p><div class="action-row" style="margin-top:22px"><button class="secondary" onclick="closeModal()">Annulla</button><button class="primary" onclick="confirmDelete('${id}')">Elimina spesa</button></div>`)}
function confirmDelete(id){state.expenses=state.expenses.filter(e=>e.id!==id);save();closeModal();render();toast('Spesa eliminata. Budget aggiornato.')}
function detail(id){const o=offers.find(o=>o.id===id),related=offers.filter(x=>x.store===o.store&&x.id!==o.id);openModal(`<div class="modal-head"><span class="store">${o.store.toUpperCase()}</span>${closeButton()}</div><img class="detail-photo" src="${o.img}" alt="${esc(o.name)}"><div class="summary-title"><span class="badge">−${o.discount}% · Esempio</span><button class="secondary" aria-label="Salva o rimuovi dai preferiti" onclick="favorite(${id});detail(${id})">${state.favorites.includes(id)?'♥':'♡'}</button></div><h2 style="margin:16px 0 5px">${o.name}</h2><p class="subtitle">${o.size}</p><div class="price" style="font-size:30px">${euro(o.price)} <del>${euro(o.old)}</del></div><p class="fine">${o.store} · Zona selezionata: ${esc(state.zone)}<br>Prezzo e scadenza dimostrativi. Posizione del negozio e disponibilità da verificare.</p><div class="action-row" style="margin-top:20px"><a class="primary" style="text-decoration:none" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(o.store+' '+state.zone)}" target="_blank" rel="noopener noreferrer">Cerca il supermercato ↗</a><button class="secondary" onclick="openFlyer('${o.store}')">Apri volantino esempio</button></div>${related.length?`<h3 style="margin:25px 0 15px">Altre offerte da ${o.store}</h3><div style="display:flex;overflow-x:auto;gap:12px">${related.map(x=>`<button class="secondary" style="min-width:160px;text-align:left" onclick="detail(${x.id})"><img src="${x.img}" alt="" style="width:100%;height:80px;object-fit:cover;border-radius:7px"><p style="margin-top:8px">${x.name}</p><b style="color:var(--green)">${euro(x.price)}</b></button>`).join('')}</div>`:''}`)}
function openFlyer(s,p=0){flyerStore=s;flyerPage=p;const os=offers.filter(o=>o.store===s),pages=Math.max(1,os.length),o=os[p];openModal(`<div class="modal-head"><h2>Volantino ${s}</h2>${closeButton()}</div><div class="notice">Sfogliabile dimostrativo · Non è il volantino ufficiale.</div><div class="flyer-cover"><div class="store">${s.toUpperCase()}</div>${o?`<img src="${o.img}" alt="${o.name}" style="height:150px;width:100%;object-fit:cover;border-radius:10px"><h2>${o.name}</h2><span class="badge">−${o.discount}%</span><div class="price" style="font-size:30px">${euro(o.price)}</div>`:'<h2>La spesa che conviene</h2>'}</div><div class="action-row" style="justify-content:space-between;margin:18px 0"><button class="secondary" ${p===0?'disabled':''} onclick="openFlyer('${s}',${p-1})">← Indietro</button><span class="fine">${p+1} / ${pages}</span><button class="secondary" ${p>=pages-1?'disabled':''} onclick="openFlyer('${s}',${p+1})">Avanti →</button></div><div class="action-row"><button class="secondary" onclick="downloadFlyer('${s}')">Scarica esempio</button><a class="primary" style="text-decoration:none" href="${official[s]}" target="_blank" rel="noopener noreferrer">Volantini ufficiali ↗</a></div>`)}
function downloadBlob(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function downloadFlyer(s){const os=offers.filter(o=>o.store===s);downloadBlob(`StudentSave-${s}-ESEMPIO.html`,`<!doctype html><html lang="it"><meta charset="utf-8"><title>Volantino dimostrativo ${s}</title><style>body{font:18px sans-serif;max-width:700px;margin:40px auto;padding:20px;color:#17523a}article{border:1px solid #ddd;padding:25px;margin:20px 0}h1{color:#007c55}</style><h1>${s} · ESEMPIO</h1><p>StudentSave · Volantino dimostrativo, non ufficiale. Prezzi e disponibilità non verificati.</p>${os.map(o=>`<article><h2>${o.name}</h2><p>${o.size}</p><strong>−${o.discount}% · ${euro(o.price)}</strong> <del>${euro(o.old)}</del></article>`).join('')}<p>Consulta il <a href="${official[s]}">sito ufficiale ${s}</a> per i volantini aggiornati.</p></html>`,'text/html;charset=utf-8');toast('Esempio scaricato in formato HTML')}
function notifications(){const list=state.notices?personalized().slice(0,2):[],prev=spent(previousMonth(currentMonth())),now=spent();openModal(`<div class="modal-head"><h2>Notifiche</h2>${closeButton()}</div><div class="group-label">Oggi · ${formatDate(today())}</div>${list.map(o=>`<button class="transaction" style="width:100%;background:none;color:inherit;text-align:left" onclick="detail(${o.id})"><span class="tx-icon">🔔</span><div class="tx-name"><b>${o.store}: ${o.name} −${o.discount}%</b><span class="tiny">Esempio adatto alle tue preferenze</span></div></button>`).join('')||`<p class="fine">${state.notices?'Nessuna offerta corrisponde alle tue scelte.':'Gli avvisi sulle offerte sono disattivati.'}</p>`}<div class="group-label">Il tuo budget</div><div class="insight"><span>💡</span><p>${esc(budgetAdvice())}</p></div>${prev>now?`<div class="transaction"><span class="tx-icon">🌱</span><div class="tx-name"><b>Hai speso ${euro(prev-now)} in meno</b><span class="tiny">Totale del mese corrente rispetto all’intero mese precedente.</span></div></div>`:''}<button class="primary" style="margin-top:20px" onclick="closeModal();go('Profilo')">Gestisci preferenze</button>`)}
function faq(){openModal(`<div class="modal-head"><h2>Assistenza e FAQ</h2>${closeButton()}</div><details open><summary>Come si aggiorna il budget?</summary><p>Ogni spesa conta nel mese della sua data. Inserimenti, modifiche e cancellazioni aggiornano automaticamente totale, saldo e grafici.</p></details><details><summary>Dove sono salvati i dati?</summary><p>Nel browser di questo dispositivo, in un profilo locale. Non vengono sincronizzati con altri dispositivi. Se cancelli i dati del browser, perdi anche i dati dell’app: usa Esporta i miei dati per conservarne una copia.</p></details><details><summary>Le offerte sono reali?</summary><p>No: prezzi, scadenze, volantini interni e punti sulla mappa sono esempi. I link ai siti ufficiali dei supermercati permettono di verificare i volantini reali.</p></details><details><summary>Come recupero il PIN?</summary><p>Non serve una password di account. Il PIN locale cifra i dati e non può essere recuperato. Puoi azzerare il profilo locale, perdendo i dati cifrati.</p></details><details><summary>Posso usare Face ID o impronta?</summary><p>La biometria nativa non è attiva in questa web-app. È disponibile il PIN per proteggere i dati sul dispositivo.</p></details>`)}
function about(){openModal(`<div class="modal-head"><h2>StudentSave</h2>${closeButton()}</div><p class="subtitle">Risparmia meglio. Vivi di più.</p><div class="notice" style="margin-top:20px">Versione 2 · Prototipo web responsive per studenti universitari.</div><p class="fine">Il sito non richiede un account. Profilo e spese sono conservati nel browser di questo dispositivo; con PIN attivo sono cifrati. Non sono sincronizzati tra dispositivi. La posizione GPS viene richiesta solo su tua azione e salvata nel profilo locale. La mappa carica tessere di OpenStreetMap; immagini prodotto e font provengono da servizi esterni. I link ai supermercati e a Google Maps aprono siti esterni. Nessuna email di recupero viene inviata da StudentSave.</p>`)}
function exportData(){downloadBlob('StudentSave-dati-'+today()+'.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Dati esportati. Il file contiene informazioni personali in chiaro.')}
function authLayout(content){document.body.classList.remove('dark');$('shell').innerHTML=`<div class="auth-page"><section class="welcome-art"><div class="pig">${pig.replace('class="logo-pig"','style="width:100%;height:100%;fill:none;stroke:currentColor;stroke-width:1.4"')}</div><h1>StudentSave</h1><p>Risparmia meglio.<br>Vivi di più.</p><p style="font-size:13px;max-width:280px;margin-top:30px">Le tue spese e le offerte vicine a te, in un unico punto.</p></section><section class="auth-content">${content}</section></div>`}
function welcome(){let hasProfile=false;try{hasProfile=!!localStorage.getItem(storageKey)}catch{}authLayout(`<div class="eyebrow" style="color:var(--green)">Il tuo futuro inizia dalle piccole scelte</div><h2>Più vita.<br>Meno pensieri al budget.</h2><p class="subtitle">Uno spazio tutto tuo per gestire le spese, scoprire le offerte e risparmiare ogni giorno.</p><button class="primary" onclick="${hasProfile?'init()':'startProfile()'}">${hasProfile?'Apri il mio profilo':'Inizia'}</button><p class="fine">Nessun account richiesto. Il tuo profilo e le tue spese rimangono nel browser di questo dispositivo. Puoi proteggerli con un PIN e scaricare una copia dei dati.</p>${hasProfile?'<button class="link" onclick="recoveryInfo()">PIN dimenticato?</button>':''}`)}
function startProfile(){state=defaultState();registration()}
function registration(){authLayout(`<div class="eyebrow" style="color:var(--green)">Benvenuto nel tuo spazio</div><h2>Facciamo conoscenza.</h2><p class="fine">Crea il tuo profilo personale su questo dispositivo. Nessun account richiesto.</p><form id="register" onsubmit="registerProfile(event)"><div class="form-grid"><label class="label-input">Nome *<input name="first" autocomplete="given-name" required maxlength="35" value="${esc(state.name?.split(' ')[0]||'')}"></label><label class="label-input">Cognome *<input name="last" autocomplete="family-name" required maxlength="35" value="${esc(state.name?.split(' ').slice(1).join(' ')||'')}"></label></div><label class="label-input">Email *<input type="email" name="email" value="${esc(state.email)}" autocomplete="email" required></label><label class="label-input">Data di nascita<input name="birth" type="date" max="${today()}" value="${esc(state.birth)}"></label><label class="label-input">Via / città universitaria *<input id="register-zone" name="zone" required maxlength="150" value="${esc(state.zone)}" oninput="delete this.dataset.coords"></label><button class="secondary" type="button" onclick="useGPS(true)">◎ Abilita posizione GPS</button><label class="label-input">PIN locale di 4 cifre (facoltativo)<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="new-password" placeholder="••••"></label><label class="label-input">Ripeti PIN<input name="confirm" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="new-password" placeholder="••••"></label><p class="fine">Con il PIN attivo i dati locali sono cifrati. Se lo dimentichi non possono essere recuperati. Face ID / impronta non sono disponibili in questa versione.</p><p class="form-error error" id="register-error" role="alert"></p><button class="primary" id="register-button">Crea il mio profilo</button></form><p class="fine">I tuoi dati rimangono su questo browser. Potrai modificare tutte le preferenze dal Profilo.</p>`)}
async function registerProfile(e){e.preventDefault();const f=new FormData(e.target),pin=f.get('pin'),confirm=f.get('confirm');if(pin!==confirm){$('register-error').textContent='I due PIN non coincidono.';return}if(!f.get('first').trim()||!f.get('last').trim()){ $('register-error').textContent='Inserisci nome e cognome.';return}const button=$('register-button');button.disabled=true;button.textContent='Creazione del profilo…';try{state.name=f.get('first').trim()+' '+f.get('last').trim();state.email=f.get('email').trim();state.birth=f.get('birth');state.zone=f.get('zone').trim();state.coords=$('register-zone').dataset.coords?JSON.parse($('register-zone').dataset.coords):null;state.onboarded=true;if(pin){const salt=crypto.getRandomValues(new Uint8Array(16));vaultKey=await deriveKey(pin,salt);localStorage.setItem(storageKey,JSON.stringify(await encryptState(state,vaultKey,salt)))}else await save();shell();render();toast('Benvenuto! Personalizza le tue preferenze dal Profilo.')}catch{state.onboarded=false;vaultKey=null;$('register-error').textContent='Impossibile salvare il profilo. Controlla che il browser consenta il salvataggio dei dati.';button.disabled=false;button.textContent='Crea il mio profilo'}}
function recoveryInfo(){openModal(`<div class="modal-head"><h2>Recupero PIN</h2>${closeButton()}</div><p class="subtitle">Il PIN protegge i dati su questo dispositivo.</p><p class="fine">Il PIN cifra i dati e non può essere recuperato. Se lo hai dimenticato puoi azzerare il profilo locale e ricominciare, perdendo le spese salvate. Se hai esportato un file, puoi conservarlo come copia dei dati.</p><button class="secondary text-danger" style="margin-top:20px" onclick="resetLocal()">Azzera il profilo locale</button>`)}
function unlockScreen(message=''){authLayout(`<div class="eyebrow" style="color:var(--green)">Il tuo spazio è protetto</div><h2>Bentornato.</h2><p class="subtitle">Inserisci il PIN del dispositivo per aprire i tuoi dati StudentSave.</p><p class="fine">Profilo locale di questo dispositivo</p><form onsubmit="unlock(event)"><label class="label-input">PIN a 4 cifre<input class="pin-digits" name="pin" type="password" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="current-password" required autofocus></label><p id="unlock-error" class="error" role="alert">${esc(message)}</p><button class="primary" id="unlock-button">Sblocca</button></form><button class="link" onclick="recoveryInfo()">PIN dimenticato?</button><button class="link" onclick="welcome()">Torna alla schermata iniziale</button><p class="fine">Face ID / impronta non sono disponibili in questa versione.</p>`)}
let failures=0,blockedUntil=0;
async function unlock(e){e.preventDefault();if(Date.now()<blockedUntil){$('unlock-error').textContent='Troppi tentativi. Riprova tra 30 secondi.';return}const button=$('unlock-button');button.disabled=true;try{const record=JSON.parse(localStorage.getItem(storageKey)),key=await deriveKey(new FormData(e.target).get('pin'),fromB64(record.salt));const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(record.iv)},key,fromB64(record.data));state=normalize(JSON.parse(new TextDecoder().decode(raw)));vaultKey=key;failures=0;shell();render()}catch{failures++;if(failures>=5){blockedUntil=Date.now()+30000;failures=0}$('unlock-error').textContent=Date.now()<blockedUntil?'Troppi tentativi. Riprova tra 30 secondi.':'PIN errato o dati non leggibili. Riprova.';button.disabled=false}}
function pinSettings(){openModal(`<div class="modal-head"><h2>${vaultKey?'Gestisci':'Imposta'} PIN</h2>${closeButton()}</div><p class="fine">Un PIN di 4 cifre cifra i dati di questo browser. Non è la password dell’account e non può essere recuperato.</p><form class="modal-form" style="margin-top:20px" onsubmit="changePin(event)">${vaultKey?'<label class="label-input">PIN attuale<input name="old" type="password" pattern="[0-9]{4}" inputmode="numeric" maxlength="4" required autocomplete="current-password"></label>':''}<label class="label-input">Nuovo PIN<input name="pin" type="password" pattern="[0-9]{4}" inputmode="numeric" maxlength="4" ${vaultKey?'':'required'} autocomplete="new-password"></label><label class="label-input">Ripeti nuovo PIN<input name="confirm" type="password" pattern="[0-9]{4}" inputmode="numeric" maxlength="4" autocomplete="new-password"></label>${vaultKey?'<p class="fine">Lascia vuoti i campi del nuovo PIN per disattivare la protezione.</p>':''}<p id="pin-error" class="error" role="alert"></p><button class="primary" id="pin-button">Salva protezione</button></form>`)}
async function changePin(e){e.preventDefault();const f=new FormData(e.target),pin=f.get('pin');if(pin!==f.get('confirm')){$('pin-error').textContent='I PIN non coincidono.';return}const button=$('pin-button');button.disabled=true;try{await pendingSave;if(vaultKey){const record=JSON.parse(localStorage.getItem(storageKey)),oldKey=await deriveKey(f.get('old'),fromB64(record.salt));await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(record.iv)},oldKey,fromB64(record.data))}if(pin){const salt=crypto.getRandomValues(new Uint8Array(16)),key=await deriveKey(pin,salt),record=await encryptState(state,key,salt);localStorage.setItem(storageKey,JSON.stringify(record));vaultKey=key}else{localStorage.setItem(storageKey,JSON.stringify(state));vaultKey=null}closeModal();render();toast(pin?'PIN attivato. I dati locali sono cifrati.':'Protezione PIN disattivata.')}catch{$('pin-error').textContent='PIN attuale errato oppure salvataggio non disponibile.';button.disabled=false}}
async function lockApp(){try{await pendingSave}catch{return}if(map){map.remove();map=null}closeModal();state=null;vaultKey=null;unlockScreen()}
async function logout(){try{await pendingSave}catch{return}if(map){map.remove();map=null}state=null;vaultKey=null;closeModal();welcome()}
function resetLocal(){openModal(`<div class="modal-head"><h2>Azzerare il profilo locale?</h2>${closeButton()}</div><p class="subtitle">Tutte le spese e le preferenze salvate su questo browser verranno eliminate. Nessun altro dispositivo verrà modificato.</p><form class="modal-form" style="margin-top:20px" onsubmit="confirmReset(event)"><label class="label-input">Scrivi ELIMINA per confermare<input name="confirm" pattern="ELIMINA" required autocomplete="off"></label><button class="primary">Elimina dati locali</button></form>`)}
function confirmReset(e){e.preventDefault();if(new FormData(e.target).get('confirm')!=='ELIMINA')return;localStorage.removeItem(storageKey);vaultKey=null;state=defaultState();closeModal();registration()}
async function init(){storageKey='studentsave-independent-v1';identity=null;try{const stored=JSON.parse(localStorage.getItem(storageKey));if(stored?.encrypted){unlockScreen();return}state=normalize(stored||defaultState());if(!state.onboarded){welcome();return}shell();render()}catch{authLayout('<h2>I dati locali non sono disponibili.</h2><p class="subtitle">Il browser potrebbe aver bloccato il salvataggio o i dati potrebbero essere danneggiati.</p><button class="primary" onclick="location.reload()">Riprova</button><button class="secondary" onclick="resetLocal()">Opzioni di recupero</button>')}}
window.addEventListener('storage',e=>{if(storageKey&&e.key===storageKey&&state){if(vaultKey){state=null;vaultKey=null;unlockScreen('Dati aggiornati in un’altra scheda. Sblocca di nuovo.')}else init()}});
init();
